<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Conversation Center V12.10 */
function tuff_beatz_conversation_messages($id){$m=get_post_meta((int)$id,'_tb_project_messages',true);return is_array($m)?$m:array();}
function tuff_beatz_conversation_is_producer($id,$uid=0){$uid=$uid?:get_current_user_id();return $uid&&user_can($uid,'edit_post',(int)$id);}
function tuff_beatz_conversation_last_read_key($id,$uid){return '_tb_message_last_read_'.(int)$uid;}
function tuff_beatz_conversation_unread($id,$uid=0){$uid=$uid?:get_current_user_id();$last=(string)get_post_meta((int)$id,tuff_beatz_conversation_last_read_key($id,$uid),true);$count=0;foreach(tuff_beatz_conversation_messages($id) as $m){if((int)($m['user_id']??0)===$uid)continue;if(!$last||strcmp((string)($m['time']??''),$last)>0)$count++;}return $count;}
function tuff_beatz_conversation_mark_read($id,$uid=0){$uid=$uid?:get_current_user_id();if($uid)update_post_meta((int)$id,tuff_beatz_conversation_last_read_key($id,$uid),current_time('mysql'));}
function tuff_beatz_conversation_send(){ $id=(int)($_POST['request_id']??0);$r=function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id).'#messages':home_url('/project-dashboard/');if(!$id||!is_user_logged_in()||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'message')){wp_safe_redirect(home_url('/start-a-project/'));exit;}if(!isset($_POST['tb_conversation_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_conversation_nonce'])),'tb_conversation_'.$id)){wp_safe_redirect($r);exit;}$body=sanitize_textarea_field(wp_unslash($_POST['message']??''));$attachments=array();if(function_exists('tuff_beatz_vault_save_files'))$attachments=tuff_beatz_vault_save_files($id,'message_files','source','Message Attachment');if(!$body&&!$attachments){wp_safe_redirect($r);exit;}$u=wp_get_current_user();$is_producer=tuff_beatz_conversation_is_producer($id,$u->ID);$sender_type=$is_producer?'producer':'client';$m=tuff_beatz_conversation_messages($id);$m[]=array('id'=>wp_generate_uuid4(),'user_id'=>$u->ID,'name'=>$u->display_name,'role'=>$is_producer?'TUFF BEATZ':'Project Member','sender_type'=>$sender_type,'body'=>$body,'attachments'=>array_values(array_filter(array_map(function($f){return $f['id']??'';},$attachments))),'time'=>current_time('mysql'));update_post_meta($id,'_tb_project_messages',$m);tuff_beatz_conversation_mark_read($id,$u->ID);if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'message','New project message from '.$u->display_name,$u->ID);if(function_exists('tuff_beatz_notify_project_message'))tuff_beatz_notify_project_message($id,$u->ID,$u->display_name,$sender_type,$body,count($attachments));wp_safe_redirect(add_query_arg('message_sent','1',$r));exit;}
add_action('admin_post_tb_conversation_send','tuff_beatz_conversation_send');
function tuff_beatz_conversation_mark_read_action(){ $id=(int)($_POST['request_id']??0);$r=tuff_beatz_project_dashboard_url($id).'#messages';if(!$id||!is_user_logged_in()||!tuff_beatz_user_can_view_request($id)){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_conversation_read_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_conversation_read_nonce'])),'tb_conversation_read_'.$id)){wp_safe_redirect($r);exit;}tuff_beatz_conversation_mark_read($id);wp_safe_redirect($r);exit;}
add_action('admin_post_tb_conversation_mark_read','tuff_beatz_conversation_mark_read_action');
function tuff_beatz_conversation_render(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_can_view_request')||!tuff_beatz_user_can_view_request($id))return;$messages=tuff_beatz_conversation_messages($id);$uid=get_current_user_id();$unread=tuff_beatz_conversation_unread($id,$uid);$vault=function_exists('tuff_beatz_vault_files')?tuff_beatz_vault_files($id):array();$byid=array();foreach($vault as $f)$byid[$f['id']??'']=$f;echo '<template id="tb-conversation-template"><section id="messages" class="tb-portal-card tb-workspace-section tb-conversation"><div class="tb-conversation-head"><div><p class="tb-card-kicker">PRIVATE PROJECT CHANNEL</p><h2>Project Conversation</h2><p>Messages and secure attachments stay connected to this production.</p></div><div class="tb-conversation-unread"><strong>'.esc_html($unread).'</strong><span>UNREAD</span></div></div>';if($unread){echo '<form class="tb-mark-read" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tb_conversation_mark_read"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_conversation_read_'.$id,'tb_conversation_read_nonce');echo '<button type="submit">Mark all read</button></form>';}echo '<div class="tb-message-list">';if(!$messages)echo '<p class="tb-empty-state">No messages yet. Start the private project conversation below.</p>';foreach($messages as $m){$sender=(string)($m['sender_type']??'');if(!$sender)$sender=tuff_beatz_conversation_is_producer($id,(int)($m['user_id']??0))?'producer':'client';$mine=(int)($m['user_id']??0)===$uid;$classes='tb-message tb-message--'.$sender.($mine?' is-mine':'');echo '<article class="'.esc_attr($classes).'"><div class="tb-message-meta"><strong>'.esc_html($m['name']??'User').'</strong><span>'.esc_html(($sender==='producer'?'TUFF BEATZ':'CLIENT').' • '.mysql2date('M j, Y g:i a',$m['time']??'')).'</span></div>';if(!empty($m['body']))echo '<p>'.nl2br(esc_html($m['body'])).'</p>';$a=is_array($m['attachments']??null)?$m['attachments']:array();if($a){echo '<div class="tb-message-attachments">';foreach($a as $fid){if(empty($byid[$fid]))continue;$f=$byid[$fid];echo '<a href="'.esc_url(tuff_beatz_vault_download_url($id,$fid)).'"><span>🔒</span><div><strong>'.esc_html($f['name']??'Attachment').'</strong><small>'.esc_html(tuff_beatz_vault_human_size($f['size']??0)).' • Secure attachment</small></div><b>↓</b></a>';}echo '</div>';}echo '</article>';}echo '</div><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'" class="tb-message-form tb-conversation-compose"><input type="hidden" name="action" value="tb_conversation_send"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_conversation_'.$id,'tb_conversation_nonce');echo '<textarea name="message" rows="4" placeholder="Write a project message..."></textarea><label class="tb-message-attach"><span>＋ Attach files</span><input type="file" name="message_files[]" multiple accept=".wav,.aiff,.aif,.mp3,.m4a,.zip,.pdf,.txt,.mid,.midi"></label><button class="btn btn-gold" type="submit">Send Message</button></form></section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-conversation-template"),old=document.getElementById("messages");if(t&&old){old.replaceWith(t.content.cloneNode(true));var list=document.querySelector("#messages .tb-message-list");if(list)list.scrollTop=list.scrollHeight;}});</script>';}
add_action('wp_footer','tuff_beatz_conversation_render',6);
function tuff_beatz_conversation_assets(){if(is_page('project-dashboard')){$p=get_template_directory().'/assets/css/conversation-center.css';if(file_exists($p))wp_enqueue_style('tuff-beatz-conversation',get_template_directory_uri().'/assets/css/conversation-center.css',array('tuff-beatz-project-portal'),filemtime($p));}}
add_action('wp_enqueue_scripts','tuff_beatz_conversation_assets',52);
